import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Link, Navigate } from "react-router-dom";
import "./App.css";

import Login from "./components/Login";
import Register from "./components/Register";
import Profile from "./components/Profile";
import CreatePost from "./components/CreatePost";
import PrivateRoute from "./components/PrivateRoute";
import authService from "./services/auth.service";

// Définir l'interface utilisateur
interface User {
  id: number;
  username: string;
  email: string;
  is_staff: boolean;
  access: string;
  refresh: string;
}

function App() {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  
  useEffect(() => {
    const user = authService.getCurrentUser();
    if (user) {
      setCurrentUser(user as User);
    }
  }, []);
  
  const logOut = () => {
    authService.logout();
    setCurrentUser(null);
  };
  
  return (
    <Router>
      <div className="App">
        <nav className="bg-gray-800 p-4">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <div className="flex items-center">
                <div className="flex-shrink-0">
                  <span className="text-white font-bold text-xl">Mabutu</span>
                </div>
                <div className="hidden md:block">
                  <div className="ml-10 flex items-baseline space-x-4">
                    <Link
                      to="/"
                      className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium"
                    >
                      Accueil
                    </Link>
                    <Link
                      to="/profile"
                      className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium"
                    >
                      Profil
                    </Link>
                    
                    {/* Lien de création de post seulement pour les administrateurs */}
                    {currentUser && currentUser.is_staff && (
                      <Link
                        to="/create-post"
                        className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium"
                      >
                        Créer un post
                      </Link>
                    )}
                  </div>
                </div>
              </div>
              <div className="hidden md:block">
                <div className="ml-4 flex items-center md:ml-6">
                  {currentUser ? (
                    <button
                      onClick={logOut}
                      className="text-white bg-red-600 hover:bg-red-700 ml-2 px-3 py-2 rounded-md text-sm font-medium"
                    >
                      Déconnexion
                    </button>
                  ) : (
                    <>
                      <Link
                        to="/register"
                        className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium"
                      >
                        S'inscrire
                      </Link>
                      <Link
                        to="/login"
                        className="text-white bg-indigo-600 hover:bg-indigo-700 ml-2 px-3 py-2 rounded-md text-sm font-medium"
                      >
                        Se connecter
                      </Link>
                    </>
                  )}
                </div>
              </div>
            </div>
          </div>
        </nav>

        <main>
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route element={<PrivateRoute />}>
              <Route path="/profile" element={<Profile />} />
              <Route path="/create-post" element={<CreatePost />} />
            </Route>
            <Route path="/" element={<Navigate to="/profile" />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
